<?php
require_once __DIR__.'/includes/security.php';
$user=require_auth(); if(!is_admin($user)){http_response_code(403);exit('Administrator permission required.');}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TTW Category Master</title><link rel="stylesheet" href="assets/app.css"><link rel="stylesheet" href="assets/automation.css"></head><body class="automation-page"><div class="app"><aside class="sidebar"><div class="brand"><img width="76" src="TTW-Logo.png" alt="TTW"><h1>Newsletter Manager</h1></div><?= sidebar_nav('categories',$user) ?></aside><main><?= app_shell_topbar('Category Master',$user) ?><div class="content auto-content"><div class="auto-layout"><section class="auto-card"><h2>Category Master</h2><p>Manage section names and aliases. Deactivating a category retains past newsletters.</p><div id="categoryList"></div></section><section class="auto-card"><h2 id="formTitle">Add Category</h2><p id="error" role="status"></p><form id="categoryForm"><input type="hidden" name="id"><label>Category name<input name="category_name" required maxlength="190"></label><label>URL slug<input name="category_slug" required pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="tourism-news"></label><label>Aliases (comma-separated)<textarea name="aliases"></textarea></label><label>Display order<input type="number" name="display_order" value="0"></label><label><input type="checkbox" name="active" checked> Active</label><div class="auto-actions"><button type="button" class="button secondary" id="newCategory">New</button><button class="button">Save category</button></div></form></section></div></div></main></div><script>
const csrf=<?= json_encode(csrf_token()) ?>;let categories=[];const form=document.getElementById('categoryForm');
async function load(){const r=await fetch('api/index.php?route=/categories');const d=await r.json();if(!r.ok)throw Error(d.error);categories=d.categories;const list=document.getElementById('categoryList');list.replaceChildren();for(const c of categories){const b=document.createElement('button');b.className='auto-recent';b.style.width='100%';b.textContent=c.category_name+' · '+(Number(c.active)?'Active':'Inactive');b.onclick=()=>{for(const key of ['id','category_name','category_slug','aliases','display_order'])form.elements[key].value=c[key];form.elements.active.checked=!!Number(c.active);document.getElementById('formTitle').textContent='Edit Category';};list.append(b);}}
form.onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(form));data.active=form.elements.active.checked;const r=await fetch('api/index.php?route=/categories',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw Error(d.error);form.reset();await load();document.getElementById('error').textContent='Category saved.';}catch(e){document.getElementById('error').textContent=e.message;}};
document.getElementById('newCategory').onclick=()=>{form.reset();form.elements.id.value='';document.getElementById('formTitle').textContent='Add Category';};load().catch(e=>document.getElementById('error').textContent=e.message);
</script></body></html>
